-- Dados vindos do banco MySQL antigo (tabelas bk_*), todos do usuário Guilherme.
-- Gerado a partir do dump de 20/11/2026; os ids originais foram mantidos, menos os dos livros.
-- Ajustes feitos na conversão:
--   * textos sem espaços nas pontas nem espaços duplos; texto vazio vira null;
--   * autores repetidos (mesmo nome, um deles com espaço no fim) viram um só;
--   * a estante sem nome (id 1) vira "sem estante";
--   * data de leitura 01/01/1900 (marcador de "não lido") vira null;
--   * a editora 648, que não existia, vira null no único livro que a usava;
--   * o vínculo com o ISBN 9786559243716, que não tinha livro, foi descartado,
--     assim como os autores que ficaram sem nenhum livro;
--   * o ISBN guardado é o oficial (o antigo tinha sufixos como -1, -2 para volumes).









select setval(pg_get_serial_sequence('paises', 'id'), coalesce((select max(id) from paises), 1));

select setval(pg_get_serial_sequence('generos', 'id'), coalesce((select max(id) from generos), 1));

select setval(pg_get_serial_sequence('formatos', 'id'), coalesce((select max(id) from formatos), 1));

select setval(pg_get_serial_sequence('autores', 'id'), coalesce((select max(id) from autores), 1));

select setval(pg_get_serial_sequence('editoras', 'id'), coalesce((select max(id) from editoras), 1));

select setval(pg_get_serial_sequence('estantes', 'id'), coalesce((select max(id) from estantes), 1));

select setval(pg_get_serial_sequence('livros', 'id'), coalesce((select max(id) from livros), 1));
